// env.json으로 web/kakao_config.js를 만든다 (Kakao JS SDK 로드).
// 사용법: dart run tool/gen_web_env.dart
import 'dart:convert';
import 'dart:io';

void main() {
  final env = jsonDecode(File('env.json').readAsStringSync()) as Map<String, dynamic>;
  final key = (env['KAKAO_JS_KEY'] as String?) ?? '';
  if (key.isEmpty) {
    stderr.writeln('env.json에 KAKAO_JS_KEY가 없다');
    exit(1);
  }
  // Kakao SDK 자체도 document.write를 사용하므로 동기 로드가 안전하다.
  File('web/kakao_config.js').writeAsStringSync(
    '// AUTO-GENERATED by tool/gen_web_env.dart — 커밋하지 마세요.\n'
    'document.write(\'<script src="https://dapi.kakao.com/v2/maps/sdk.js?appkey=$key"><\\/script>\');\n',
  );
  stdout.writeln('web/kakao_config.js yaratildi');
}
